def choose_move(observation):
    def pos(v, default=(0, 0)):
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def manhattan(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def choose_toward(src, dst):
        return [clamp_step(src[0], dst[0]), clamp_step(src[1], dst[1])]

    def choose_away(src, dst):
        return [-clamp_step(src[0], dst[0]), -clamp_step(src[1], dst[1])]

    def pseudo_key(x, y, seed=0):
        n = x * 73856093 + y * 19349663 + seed * 83492791
        if n < 0:
            n = -n
        return n

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos(observation.get("self_position", (0, 0)))
    ox, oy = pos(observation.get("opponent_position", (sx, sy)))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return choose_toward(self_pos, opp_pos)
        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        corners = [(0, 0), (0, max(0, gh - 1)), (max(0, gw - 1), 0), (max(0, gw - 1), max(0, gh - 1))]
        target = max(corners, key=lambda c: (manhattan(c, opp_pos), -pseudo_key(c[0], c[1], sx + sy)))
        return choose_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        if targets:
            best = min(targets, key=lambda t: (manhattan(pos(t, self_pos), self_pos), pseudo_key(pos(t, self_pos)[0], pos(t, self_pos)[1], ox + oy)))
            return choose_toward(self_pos, pos(best, self_pos))
        gw = observation.get("grid_width", 0) or 0
        gh = observation.get("grid_height", 0) or 0
        if gw and gh:
            center = (gw // 2, gh // 2)
            return choose_toward(self_pos, center)
        return choose_away(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    if resources:
        best = min(resources, key=lambda r: (manhattan(pos(r, self_pos), self_pos), pseudo_key(pos(r, self_pos)[0], pos(r, self_pos)[1], sx * 3 + sy * 7)))
        return choose_toward(self_pos, pos(best, self_pos))

    # Fallbacks: if opponent is nearby, avoid; otherwise drift to center if known.
    gw = observation.get("grid_width", 0) or 0
    gh = observation.get("grid_height", 0) or 0
    if gw and gh:
        center = (gw // 2, gh // 2)
        if manhattan(self_pos, opp_pos) <= 2:
            return choose_away(self_pos, opp_pos)
        return choose_toward(self_pos, center)

